package lk.ac.sliit.ridelink.driver.presentation.controller;
import io.swagger.v3.oas.annotations.security.SecurityRequirement; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.Valid; import lk.ac.sliit.ridelink.driver.application.dto.request.*; import lk.ac.sliit.ridelink.driver.application.dto.response.VehicleResponse; import lk.ac.sliit.ridelink.driver.application.port.in.DriverVehicleUseCase; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.UUID;
@RestController @RequestMapping("/api/v1/vehicles") @Tag(name="Vehicles") @SecurityRequirement(name="bearerAuth") public class VehicleController { private final DriverVehicleUseCase service; public VehicleController(DriverVehicleUseCase s){service=s;} private boolean admin(Authentication a){return a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_ADMIN"));} private UUID id(Authentication a){return UUID.fromString(a.getName());}
 @GetMapping("/{vehicleId}") public VehicleResponse get(Authentication a,@PathVariable UUID vehicleId){return service.getVehicle(id(a),admin(a),vehicleId);} @PatchMapping("/{vehicleId}") public VehicleResponse update(Authentication a,@PathVariable UUID vehicleId,@Valid @RequestBody UpdateVehicleRequest r){return service.updateVehicle(id(a),admin(a),vehicleId,r);} @PatchMapping("/{vehicleId}/active") public VehicleResponse active(Authentication a,@PathVariable UUID vehicleId,@RequestBody VehicleActiveRequest r){return service.setVehicleActive(id(a),admin(a),vehicleId,r.active());}
}
